/**
 * Retrieval-time prediction API (Phase 9b).
 *
 * Answers the customer's question — "how long until my car is here?" — and the
 * dispatcher's question — "when should a valet actually set off?".
 *
 * **These estimates come from a baseline model trained on synthetic data.** It
 * was fitted offline to a history generated by `ai/retrieval/dataset.py` and has
 * never seen a real valet operation. Every response carries
 * `trained_on_synthetic_data: true`, a `data_basis` string and a `disclaimer`;
 * `RETRIEVAL_PROTOTYPE_NOTICE` in `utils/constants` is the fallback wording when
 * a card is rendered without them. The brief requires this labelling and the UI
 * must not drop it, because an "8 minutes" with no stated origin reads as a
 * promise.
 *
 * **What the numbers mean.** The live half of each estimate is measured: queue
 * length, staff on duty, zone occupancy and whether the vehicle is flagged are
 * read from the database. Only the conversion from those counts into minutes is
 * estimated. `contributions` gives the per-feature share of the estimate in
 * minutes, so the figure can be interrogated rather than taken on trust.
 *
 * See `docs/AI-INTEGRITY.md`.
 */

import { apiGet, apiPost } from './apiClient'
import { ENDPOINTS } from './endpoints'

/**
 * Estimate a retrieval for a real custody session, and store it.
 *
 * The backend measures the queue, staffing and zone state itself — no features
 * are passed in. Passing a `custodySessionId` together with `features` is
 * rejected, because silently ignoring caller-supplied inputs would leave the UI
 * showing an estimate whose inputs the caller believed they had chosen.
 *
 * Resolves with the estimate plus `estimated_retrieval_time`,
 * `estimated_minutes`, `queue_position`, `recommended_dispatch_time` and
 * `recommended_dispatch` (a short human phrase such as `Now` or
 * `In 4 minutes`).
 */
export function requestRetrievalPrediction(custodySessionId, { persist = true } = {}) {
  return apiPost(ENDPOINTS.retrievalPredict, {
    custody_session_id: custodySessionId,
    persist,
  })
}

/**
 * The estimate stored for a custody session.
 *
 * Returns what the customer was told, not a fresh number: the queue has moved
 * since, and silently re-answering would mean the figure on screen no longer
 * exists anywhere in the record. Rejects with a 404-shaped error when no
 * estimate has been generated yet — render that as "not estimated yet" with a
 * button to request one, not as a failure.
 */
export function fetchRetrievalPrediction(custodySessionId) {
  return apiGet(ENDPOINTS.retrievalPrediction(custodySessionId))
}

/**
 * Metadata for the predictor, including the held-out MAE and the median
 * baseline it had to beat.
 *
 * Resolves with `available: false` plus a `reason` naming the training script
 * when no artifact exists. That is a supported state, so callers should show the
 * reason rather than an error.
 */
export function fetchRetrievalModelInfo() {
  return apiGet(ENDPOINTS.retrievalModel)
}

/**
 * Score a supplied feature set without writing anything.
 *
 * Every feature the model was trained on is required; the backend names any that
 * are missing rather than defaulting them to zero, because a confident estimate
 * from a partly-guessed input is the failure this refusal exists to prevent.
 */
export function scoreRetrievalWhatIf(features) {
  return apiPost(ENDPOINTS.retrievalPredict, { features })
}

/**
 * The largest per-feature contributions, for display under an estimate.
 *
 * Contributions are in minutes and signed: positive adds to the wait, negative
 * shortens it. Entries whose effect is below `threshold` minutes are dropped, so
 * a card does not list six factors that between them move the answer by a few
 * seconds and bury the two that matter.
 */
export function topContributions(estimate, limit = 3, threshold = 0.25) {
  const contributions = estimate?.contributions
  if (!contributions || typeof contributions !== 'object') return []
  return Object.entries(contributions)
    .map(([feature, minutes]) => ({ feature, minutes: Number(minutes) || 0 }))
    .filter((entry) => Math.abs(entry.minutes) >= threshold)
    .sort((a, b) => Math.abs(b.minutes) - Math.abs(a.minutes))
    .slice(0, limit)
}

/**
 * The provenance wording to show alongside an estimate.
 *
 * Prefers the backend's own `data_basis` and `disclaimer` over any local
 * constant, so what the UI says is always what the service that produced the
 * number said. Falls back to `RETRIEVAL_PROTOTYPE_NOTICE` when they are absent.
 */
export function retrievalProvenance(estimate, fallbackNotice) {
  return {
    dataBasis: estimate?.data_basis ?? null,
    disclaimer: estimate?.disclaimer ?? fallbackNotice ?? null,
    trainedOnSyntheticData: estimate?.trained_on_synthetic_data ?? true,
    modelVersion: estimate?.model_version ?? null,
    method: estimate?.method ?? null,
  }
}

/**
 * Format a wait as a phrase for the estimate card.
 *
 * Returns a range whenever both bounds are present, because a single number
 * implies a precision this model does not have.
 */
export function formatWait(estimate) {
  if (!estimate) return null
  const minutes = estimate.estimated_minutes ?? estimate.predicted_wait_minutes
  if (minutes === null || minutes === undefined) return null
  const min = estimate.min_wait_minutes
  const max = estimate.max_wait_minutes
  if (min !== null && max !== null && min !== undefined && max !== undefined && min !== max) {
    return `${min}–${max} minutes`
  }
  return `${minutes} minute${Number(minutes) === 1 ? '' : 's'}`
}
